 c.setFillColor(HexColor('#9f7bea'));c.setFont('Regular',8);c.drawString(44,H-36,'DENIS LANVEN / SKYCOACH / HR STRATEGY')
 c.setStrokeColor(HexColor('#372744'));c.line(44,H-50,W-44,H-50)
 y=H-78;y=para(label,y,'small');y=para(title,y,'title')
